budget.value:
fun p =>
  have v := fun t i => ↑(p.h i) / ((1 - t) * ↑(p.h i) + t);
  have u := fun t i => ↑↑p.n * v t i / ∑ j, v t j;
  have t := if h : ∃ t, 0 ≤ t ∧ min (1 - t) (↑↑p.n * p.ρ - ∑ i, u t i ^ 2) = 0 then h.choose else 0;
  have a := fun i => p.μ * u t i;
  have I := ∑ i, a i ^ 2 / ↑(p.h i);
  have S := ∑ i, (↑(p.h i))⁻¹;
  have U := Finset.univ.sup' ⋯ a;
  have M :=
    p.L * max (U * min (↑↑p.n) (1 + √(↑↑p.n * (p.ρ - 1)))) ((↑↑p.n * Finset.univ.sup' ⋯ fun i => a i / ↑(p.h i)) / S);
  have A := 2 * S * M / I;
  have w := ⌈2 + ↑p.d + A + (p.R ^ 2 + (p.σ * U / M) ^ 2) / p.ε⌉₊.size;
  (2048 *
      (p.σ ^ 2 / (I * p.ε) +
        A * (1 + Real.log (1 + p.R ^ 2 / p.ε)) *
          (↑(Finset.univ.sup p.h) + ↑p.l + ↑p.b * (64 + 1024 * ↑p.d * ↑w)))).toNNReal

